 "groupId" varchar(180) NOT NULL, "sourceCode" varchar(180) NOT NULL,
 "kind" varchar(120) NOT NULL, "role" varchar(30) NOT NULL,
 "optionAmount" varchar(80), "amountMeaning" varchar(30) NOT NULL,
 "sourceHash" varchar(64) NOT NULL, "createdAtMs" bigint NOT NULL,
 CONSTRAINT "component_not_self" CHECK ("parentProductId" <> "componentProductId")
);
